/**
 * Object storage for uploaded contracts and org exports. The API writes; the
 * worker reads for extraction and writes exports. Keys are
 * `<orgId>/contracts/<contractId>` and `<orgId>/exports/<exportId>.tar.gz`,
 * generated by slai, never taken from user input.
 */
import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import { dirname, isAbsolute, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";
import {
  CreateBucketCommand,
  DeleteObjectCommand,
  GetObjectCommand,
  HeadBucketCommand,
  PutObjectCommand,
  S3Client,
  type ServerSideEncryption,
} from "@aws-sdk/client-s3";

export interface StorageDriver {
  put(key: string, data: Uint8Array, meta: { contentType: string; sha256: string }): Promise<void>;
  get(key: string): Promise<Uint8Array>;
  delete(key: string): Promise<void>;
}

const KEY = /^[A-Za-z0-9][A-Za-z0-9/_.-]{0,500}$/;

function checkKey(key: string): string {
  if (!KEY.test(key) || key.includes("..")) throw new Error("invalid storage key");
  return key;
}

/** Writes files under `root`. For development and single-node self-hosting. */
export function createLocalStorage(root: string): StorageDriver {
  const base = resolve(root);
  const pathOf = (key: string) => {
    const p = resolve(base, checkKey(key));
    if (!p.startsWith(base + sep)) throw new Error("invalid storage key");
    return p;
  };
  return {
    async put(key, data) {
      const p = pathOf(key);
      await mkdir(dirname(p), { recursive: true, mode: 0o700 });
      await writeFile(p, data, { mode: 0o600 });
    },
    async get(key) {
      return new Uint8Array(await readFile(pathOf(key)));
    },
    async delete(key) {
      await rm(pathOf(key), { force: true });
    },
  };
}

/**
 * Server-side encryption for the s3 driver:
 * - `AES256`: SSE-S3 (AWS, MinIO with KMS configured);
 * - `aws:kms`: SSE-KMS with `S3_SSE_KMS_KEY_ID` (a customer-managed key);
 * - `provider`: send no SSE header, for providers that always encrypt at rest
 *   and reject the AWS header (GCS interop, R2). Choose it deliberately.
 */
export type S3Sse = "AES256" | "aws:kms" | "provider";

export interface S3StorageOptions {
  bucket: string;
  region: string;
  /** Unset for AWS; the S3 API endpoint for GCS (https://storage.googleapis.com), R2 or MinIO. */
  endpoint?: string;
  /** MinIO and most self-hosted servers need path-style URLs. */
  forcePathStyle?: boolean;
  /**
   * Static credentials. Leave unset in production on AWS to use the SDK's
   * default chain (workload identity: ECS task role, EKS IRSA/pod identity, IMDS).
   * GCS interop and R2 need HMAC keys here (from the secrets manager).
   */
  accessKeyId?: string;
  secretAccessKey?: string;
  sse: S3Sse;
  kmsKeyId?: string;
  /** Prepended to every key, e.g. `prod/`. */
  prefix?: string;
  /** Refuse to overwrite an existing object (If-None-Match: *). Default true. */
  writeOnce?: boolean;
}

/**
 * S3-compatible object storage: AWS S3, GCS (XML API interop), Cloudflare R2
 * and MinIO. Objects carry Content-Type and a `sha256` metadata field; keys are
 * write-once by default. Deletes remove the current version; on a versioned
 * bucket a lifecycle rule must expire noncurrent versions (see TR-25a).
 */
export function createS3Storage(opts: S3StorageOptions, client?: S3Client): StorageDriver {
  const s3 = client ?? s3Client(opts);
  const fullKey = (key: string) => `${opts.prefix ?? ""}${checkKey(key)}`;
  const sse: { ServerSideEncryption?: ServerSideEncryption; SSEKMSKeyId?: string } =
    opts.sse === "provider"
      ? {}
      : opts.sse === "aws:kms"
        ? { ServerSideEncryption: "aws:kms", ...(opts.kmsKeyId && { SSEKMSKeyId: opts.kmsKeyId }) }
        : { ServerSideEncryption: "AES256" };
  return {
    async put(key, data, meta) {
      await s3.send(
        new PutObjectCommand({
          Bucket: opts.bucket,
          Key: fullKey(key),
          Body: data,
          ContentType: meta.contentType,
          ContentLength: data.byteLength,
          Metadata: { sha256: meta.sha256 },
          ...(opts.writeOnce !== false && { IfNoneMatch: "*" }),
          ...sse,
        }),
      );
    },
    async get(key) {
      const out = await s3.send(new GetObjectCommand({ Bucket: opts.bucket, Key: fullKey(key) }));
      if (!out.Body) throw new Error("storage object has no body");
      return out.Body.transformToByteArray();
    },
    async delete(key) {
      await s3.send(new DeleteObjectCommand({ Bucket: opts.bucket, Key: fullKey(key) }));
    },
  };
}

export function s3Client(opts: S3StorageOptions): S3Client {
  return new S3Client({
    region: opts.region,
    ...(opts.endpoint && { endpoint: opts.endpoint }),
    forcePathStyle: opts.forcePathStyle ?? false,
    ...(opts.accessKeyId &&
      opts.secretAccessKey && {
        credentials: { accessKeyId: opts.accessKeyId, secretAccessKey: opts.secretAccessKey },
      }),
    // GCS and R2 reject the SDK's default flexible checksums; send them only when an operation requires one.
    requestChecksumCalculation: "WHEN_REQUIRED",
    responseChecksumValidation: "WHEN_REQUIRED",
  });
}

/** Creates the bucket if it is missing. Local and staging only; production buckets come from infrastructure code. */
export async function ensureS3Bucket(opts: S3StorageOptions): Promise<void> {
  const s3 = s3Client(opts);
  try {
    await s3.send(new HeadBucketCommand({ Bucket: opts.bucket }));
  } catch {
    await s3.send(new CreateBucketCommand({ Bucket: opts.bucket }));
  } finally {
    s3.destroy();
  }
}

/** Reads the s3 driver's options from S3_* variables. */
export function s3OptionsFromEnv(env: NodeJS.ProcessEnv = process.env): S3StorageOptions {
  const v = (k: string) => (env[k] === "" ? undefined : env[k]);
  const bucket = v("S3_BUCKET");
  if (!bucket) throw new Error("S3_BUCKET is required when STORAGE_DRIVER=s3");
  const sse = (v("S3_SSE") ?? "AES256") as S3Sse;
  if (!["AES256", "aws:kms", "provider"].includes(sse)) throw new Error("S3_SSE must be AES256, aws:kms or provider");
  if (sse === "aws:kms" && !v("S3_SSE_KMS_KEY_ID")) throw new Error("S3_SSE=aws:kms needs S3_SSE_KMS_KEY_ID");
  return {
    bucket,
    region: v("S3_REGION") ?? "us-east-1",
    endpoint: v("S3_ENDPOINT"),
    forcePathStyle: v("S3_FORCE_PATH_STYLE") === "true",
    accessKeyId: v("S3_ACCESS_KEY_ID"),
    secretAccessKey: v("S3_SECRET_ACCESS_KEY"),
    sse,
    kmsKeyId: v("S3_SSE_KMS_KEY_ID"),
    prefix: v("S3_PREFIX"),
    writeOnce: v("S3_WRITE_ONCE") !== "false",
  };
}

export type StorageDriverName = "local" | "s3";

export function createStorage(opts: { driver: string; localDir: string; s3?: S3StorageOptions }): StorageDriver {
  if (opts.driver === "local") return createLocalStorage(resolveFromRepoRoot(opts.localDir));
  if (opts.driver === "s3") return createS3Storage(opts.s3 ?? s3OptionsFromEnv());
  throw new Error(`storage driver "${opts.driver}" is not implemented (use local or s3)`);
}

const REPO_ROOT = fileURLToPath(new URL("../../../", import.meta.url));

/**
 * Relative STORAGE_LOCAL_DIR values are taken from the repo root (where .env
 * lives), so the API and the worker, which run from different package
 * directories, read and write the same files.
 */
export function resolveFromRepoRoot(dir: string): string {
  return isAbsolute(dir) ? dir : resolve(REPO_ROOT, dir);
}

export const contractStorageKey = (orgId: string, contractId: string) => `${orgId}/contracts/${contractId}`;
export const exportStorageKey = (orgId: string, exportId: string) => `${orgId}/exports/${exportId}.tar.gz`;
